from pathlib import Path

p = Path('sethiportfolio.html')
s = p.read_text(encoding='utf-8')

old_header = '''        <header class="py-5 px-6 border-b border-gray-200 bg-white">\n            <div class="max-w-[1500px] mx-auto flex flex-col md:flex-row md:items-center md:justify-between gap-2">\n                <h1 class="text-3xl md:text-4xl font-black tracking-tight text-gray-900">SETHI<span class="text-yellow-600">PORTFOLIO</span></h1>\n                <p class="text-sm text-gray-500 md:text-right max-w-2xl">Transparent portfolio decisions, performance and the reasoning behind every allocation.</p>\n            </div>\n        </header>'''
new_header = '''        <header class="py-4 px-6 border-b border-gray-200 bg-white text-center">\n            <h1 class="text-3xl md:text-4xl font-black tracking-tight text-gray-900">SETHI<span class="text-yellow-600">PORTFOLIO</span></h1>\n        </header>'''
if old_header not in s:
    raise SystemExit('Header marker not found')
s = s.replace(old_header, new_header, 1)

start = s.index('            <!-- PORTFOLIO IDENTITY -->')
end = s.index('            <!-- COMPOSITION + HOLDINGS -->')

replacement = '''            <!-- ABOVE-THE-FOLD PORTFOLIO HERO -->\n            <section class="grid grid-cols-1 xl:grid-cols-[360px_minmax(0,1fr)] gap-4 items-stretch">\n                <!-- PORTFOLIO IDENTITY -->\n                <div class="bg-white border border-gray-200 rounded-2xl shadow-sm p-4 md:p-5 flex flex-col">\n                    <div class="flex flex-wrap items-center gap-2 mb-2">\n                        <select class="bg-gray-900 text-white text-sm font-black rounded-lg px-4 py-2 outline-none w-full">\n                            <option>Fundamental Portfolio</option>\n                        </select>\n                        <span class="text-[9px] font-black uppercase tracking-widest text-amber-700 bg-amber-50 border border-amber-200 rounded-full px-2.5 py-1">Public Portfolio</span>\n                        <span class="text-[9px] font-black uppercase tracking-widest text-gray-500 bg-gray-50 border border-gray-200 rounded-full px-2.5 py-1">Illustrative V1 Data</span>\n                    </div>\n                    <h2 class="text-2xl font-black tracking-tight text-gray-900">Fundamental Portfolio</h2>\n                    <p class="text-sm text-gray-500 mt-1.5 leading-relaxed">\n                        Bottom-up equities focused on durable quality, valuation discipline and long-term capital allocation. Every material change links to a dated investment note.\n                    </p>\n\n                    <div class="grid grid-cols-2 gap-2.5 mt-4">\n                        <div class="rounded-xl bg-gray-900 text-white px-3.5 py-3"><p class="text-[9px] uppercase tracking-widest font-black text-gray-400">Portfolio Value</p><p class="text-xl font-black mt-0.5">£100,000</p></div>\n                        <div class="rounded-xl bg-emerald-50 border border-emerald-100 px-3.5 py-3"><p class="text-[9px] uppercase tracking-widest font-black text-emerald-700">Total Return</p><p class="text-xl font-black mt-0.5 text-emerald-700">+12.8%</p></div>\n                        <div class="rounded-xl bg-gray-50 border border-gray-100 px-3.5 py-3"><p class="text-[9px] uppercase tracking-widest font-black text-gray-400">Vs S&amp;P 500</p><p class="text-xl font-black mt-0.5 text-gray-900">+3.6pp</p></div>\n                        <div class="rounded-xl bg-gray-50 border border-gray-100 px-3.5 py-3"><p class="text-[9px] uppercase tracking-widest font-black text-gray-400">Since</p><p class="text-xl font-black mt-0.5 text-gray-900">Jun 2026</p></div>\n                    </div>\n\n                    <div class="mt-auto pt-3"><span class="text-[9px] text-gray-400 bg-gray-50 border border-gray-100 rounded-full px-2.5 py-1">Illustrative only · not a live track record</span></div>\n                </div>\n\n                <!-- PERFORMANCE HERO -->\n                <div class="bg-white border border-gray-200 rounded-2xl shadow-sm p-4 md:p-5 min-w-0">\n                    <div class="flex flex-col lg:flex-row lg:items-start lg:justify-between gap-3 mb-2">\n                        <div>\n                            <p class="text-[10px] font-black uppercase tracking-widest text-blue-600 mb-1">Performance</p>\n                            <h3 class="text-xl md:text-2xl font-black text-gray-900">Portfolio vs Benchmarks</h3>\n                            <p class="text-xs text-gray-500 mt-0.5">Rebased to 100 for a like-for-like comparison.</p>\n                        </div>\n                        <div class="flex flex-wrap items-center gap-2">\n                            <div class="flex rounded-lg bg-gray-100 p-1 text-xs font-black">\n                                <button onclick="setRange('1M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1M</button>\n                                <button onclick="setRange('3M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">3M</button>\n                                <button onclick="setRange('YTD', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">YTD</button>\n                                <button onclick="setRange('1Y', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1Y</button>\n                                <button onclick="setRange('SI', this)" class="range-btn px-3 py-1.5 rounded-md bg-white text-blue-700 shadow-sm">Since Inception</button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="flex flex-wrap gap-2 mb-1">\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-blue-50 text-blue-700 border border-blue-200 text-xs font-black" data-series="portfolio">● Sethi Portfolio</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="sp500">● S&amp;P 500</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="nasdaq">● Nasdaq-100</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="vwrl">● VWRL</button>\n                    </div>\n                    <div id="performance-chart" style="height:330px"></div>\n                </div>\n            </section>\n\n'''

s = s[:start] + replacement + s[end:]
p.write_text(s, encoding='utf-8')
